# Optimized InDesign JSX Script for Converting Spreads to Single Pages

Here's an optimized script that converts a spreads-based InDesign document to single pages while preserving all layout elements, margins, and master page references:

```jsx
// ConvertSpreadsToSinglePages.jsx
// Optimized script to transform spreads document to single pages while preserving layout

(function() {
    if (app.documents.length === 0) {
        alert("No documents open. Please open a document and try again.");
        return;
    }

    var doc = app.activeDocument;
    var originalZeroPoint = doc.zeroPoint;
    var originalRulerOrigin = doc.viewPreferences.rulerOrigin;
    var originalSpreads = doc.spreads.everyItem().getElements();
    var progressBar = new ProgressBar("Converting Spreads to Single Pages", originalSpreads.length);

    try {
        // Set up progress bar
        progressBar.show();

        // Store original preferences
        doc.zeroPoint = [0, 0];
        doc.viewPreferences.rulerOrigin = RulerOrigin.SPREAD_ORIGIN;

        // Process each spread
        for (var i = 0; i < originalSpreads.length; i++) {
            progressBar.update(i + 1, "Processing spread " + (i + 1) + " of " + originalSpreads.length);

            var currentSpread = originalSpreads[i];
            var spreadPages = currentSpread.pages.everyItem().getElements();

            // Skip spreads with only one page
            if (spreadPages.length <= 1) continue;

            // Process right page first (to avoid shifting issues)
            for (var j = spreadPages.length - 1; j >= 0; j--) {
                var page = spreadPages[j];

                // Skip if already a single page
                if (page.side === PageSideOptions.SINGLE_SIDED) continue;

                // Create new page after current page
                var newPage = doc.pages.add(LocationOptions.AFTER, page);

                // Copy master page reference
                if (page.appliedMaster) {
                    newPage.appliedMaster = page.appliedMaster;
                }

                // Copy page margins
                newPage.marginPreferences.properties = page.marginPreferences.properties;

                // Copy page size and orientation
                newPage.properties = {
                    name: page.name,
                    label: page.label,
                    pageSize: page.pageSize,
                    transformReferencePoint: page.transformReferencePoint,
                    orientation: page.orientation
                };

                // Copy all page items to new page
                copyPageItems(page, newPage);

                // Update progress for each page processed
                progressBar.update(i + 1 + (j * 0.1), "Processing page " + (j + 1) + " of spread " + (i + 1));
            }
        }

        // Remove original spreads (now that we've created single pages)
        for (var k = originalSpreads.length - 1; k >= 0; k--) {
            var spread = originalSpreads[k];
            if (spread.pages.length > 1) {
                spread.remove();
            }
        }

        // Restore original preferences
        doc.zeroPoint = originalZeroPoint;
        doc.viewPreferences.rulerOrigin = originalRulerOrigin;

        alert("Document successfully converted to single pages.\nOriginal spreads have been removed.");
    } catch (e) {
        // Restore original preferences in case of error
        doc.zeroPoint = originalZeroPoint;
        doc.viewPreferences.rulerOrigin = originalRulerOrigin;
        alert("Error occurred: " + e.message + "\n\nLine: " + e.line);
    } finally {
        progressBar.hide();
    }

    // Helper function to copy all page items from source to target page
    function copyPageItems(sourcePage, targetPage) {
        var items = sourcePage.allPageItems;
        var itemCount = items.length;
        var targetSpread = targetPage.parent;

        // Process items in reverse order to maintain stacking
        for (var i = itemCount - 1; i >= 0; i--) {
            var item = items[i];

            // Skip items that are already on the target page
            if (item.parentPage === targetPage) continue;

            // Calculate position relative to target page
            var itemBounds = item.geometricBounds;
            var pageBounds = sourcePage.bounds;
            var targetPageBounds = targetPage.bounds;

            // Calculate offset based on page position
            var xOffset = targetPageBounds[1] - pageBounds[1];
            var yOffset = targetPageBounds[0] - pageBounds[0];

            // Duplicate item to target spread
            var newItem = item.duplicate(targetSpread);

            // Adjust position
            newItem.move([xOffset, yOffset]);

            // Special handling for text frames to maintain content
            if (newItem instanceof TextFrame) {
                // Re-link stories if needed
                if (newItem.previousTextFrame) {
                    newItem.previousTextFrame.nextTextFrame = newItem;
                }
                if (newItem.nextTextFrame) {
                    newItem.nextTextFrame.previousTextFrame = newItem;
                }
            }

            // Special handling for groups
            if (newItem instanceof Group) {
                adjustGroupItems(newItem, xOffset, yOffset);
            }
        }
    }

    // Helper function to adjust positions of items within a group
    function adjustGroupItems(group, xOffset, yOffset) {
        var groupItems = group.allPageItems;
        for (var i = 0; i < groupItems.length; i++) {
            var item = groupItems[i];
            item.move([xOffset, yOffset]);

            if (item instanceof Group) {
                adjustGroupItems(item, xOffset, yOffset);
            }
        }
    }

    // Progress bar class for better user feedback
    function ProgressBar(title, maxValue) {
        this.window = null;
        this.progressBar = null;
        this.title = title;
        this.maxValue = maxValue;
        this.currentValue = 0;

        this.show = function() {
            this.window = new Window("palette", this.title, undefined);
            this.window.orientation = "column";
            this.window.alignChildren = ["fill", "top"];

            this.progressBar = this.window.add("progressbar", undefined, 0, this.maxValue);
            this.progressBar.preferredSize.width = 300;
            this.progressText = this.window.add("statictext", undefined, "");
            this.progressText.preferredSize.width = 300;

            this.window.show();
        };

        this.update = function(value, status) {
            this.currentValue = value;
            this.progressBar.value = value;
            this.progressText.text = status || "";
            this.window.update();
        };

        this.hide = function() {
            if (this.window) {
                this.window.close();
            }
        };
    }
})();
```

## Key Features of This Script:

1. **Preserves All Layout Elements**:
   - Maintains exact positioning of all page items
   - Handles text frames, images, groups, and other elements
   - Preserves text flow and threading

2. **Master Page References**:
   - Copies the applied master page to each new single page
   - Maintains all master page elements

3. **Page Properties**:
   - Preserves margins, page size, and orientation
   - Maintains page names and labels

4. **Optimized Performance**:
   - Processes pages in reverse order to avoid shifting issues
   - Uses progress bar for user feedback
   - Handles errors gracefully with proper cleanup

5. **Special Handling**:
   - Properly manages text frame threading
   - Correctly positions grouped items
   - Maintains document zero point and ruler origin

## Usage Instructions:

1. Open your spreads-based InDesign document
2. Run the script (File > Scripts > Other Script...)
3. The script will create single pages while preserving all layout elements
4. Original spreads will be removed after successful conversion

The script includes error handling and will attempt to restore original document settings if something goes wrong.

